import { useEffect, useState } from "react";
import { useParams, Link } from "react-router-dom";  // За получаване на projectId от URL
import { getDetailsProject } from "../../services/admin/getDetailsProject";


export default function Details() {
    const [project, setProject] = useState(null);  // Стейт за съхраняване на данните за проекта
    const [loading, setLoading] = useState(true);  // Стейт за показване на "loading" съобщение
    const { projectId } = useParams();  // Вземане на projectId от URL параметрите

    // Използваме useEffect за извличане на данни за проекта
    useEffect(() => {
        const fetchProject = async () => {
            try {
                // Извикваме service функцията за да получим данни за проекта
                const data = await getDetailsProject(projectId);
                setProject(data);  // Записваме данните в стейта
            } catch (error) {
                console.error("Failed to fetch project:", error);
            } finally {
                setLoading(false);  // След като заредим данните, премахваме "loading"
            }
        };

        fetchProject();  // Извикваме функцията за извличане на данни
    }, [projectId]);  // Се стартира отново, ако projectId се промени

    // Ако все още зареждаме данни, показваме съобщение
    if (loading) {
        return <p>Loading project details...</p>;
    }

    // Ако проектът не е намерен
    if (!project) {
        return <p>Project not found!</p>;
    }

    return (
        <div className="container-details">
            <header className="header-details">
                <h1 id="details-title">{project.title}</h1>  {/* Показваме заглавието на проекта */}
            </header>
            <main style={{ marginBottom: "30px" }}>
                <div className="project-image">
                    <img src={project.img} alt="Project Image" />  {/* Показваме картината на проекта */}
                </div>
                <div className="project-description">
                    <p id="desc">{project.description}</p>  {/* Показваме описанието на проекта */}
                </div>
                {project.gitLink && (
                    <a href={project.gitLink} target="_blank" rel="noopener noreferrer">
                        View on GitHub  {/* Показваме линк към GitHub, ако има такъв */}
                    </a>
                )}
            </main>
            {/* Ако потребителят е администратор, показваме линкове за редактиране и изтриване */}
            <Link
                className="readedMessage"
                to={`/update/${projectId}`}
                style={{ margin: "10px" }}
            >
                Edit
            </Link>
            <Link
                className="readedMessage"
                to={`/delete/${projectId}`}
                style={{ margin: "10px" }}
            >
                Delete
            </Link>
        </div>
    );
}
